// Service worker: precaches the whole app so it runs with no network at all.
// The list and version below are generated by `npm run build` (scripts/build-sw.mjs).

const VERSION = 'problab-619d4f505667';
const PRECACHE = [
  './',
  './css/app.css',
  './icons/apple-touch-icon.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './icons/icon.svg',
  './index.html',
  './js/app.js',
  './js/core/events.js',
  './js/core/prob.js',
  './js/core/results.js',
  './js/core/rng.js',
  './js/core/runner.js',
  './js/experiments/birthday.js',
  './js/experiments/cards.js',
  './js/experiments/coins.js',
  './js/experiments/dice.js',
  './js/experiments/galton.js',
  './js/experiments/index.js',
  './js/experiments/marbles.js',
  './js/experiments/monty.js',
  './js/experiments/spinner.js',
  './js/stages/birthday.js',
  './js/stages/cards.js',
  './js/stages/coins.js',
  './js/stages/dice.js',
  './js/stages/galton.js',
  './js/stages/index.js',
  './js/stages/marbles.js',
  './js/stages/monty.js',
  './js/stages/spinner.js',
  './js/stages/util.js',
  './js/ui/chart-util.js',
  './js/ui/controls.js',
  './js/ui/convergence.js',
  './js/ui/format.js',
  './js/ui/histogram.js',
  './js/ui/icons.js',
  './js/ui/learn.js',
  './js/ui/sheet.js',
  './js/ui/sound.js',
  './js/ui/storage.js',
  './manifest.webmanifest',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION)
      .then((cache) => cache.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('problab-') && k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    // App shell: serve the cached page instantly; works offline.
    event.respondWith(
      caches.match('./index.html').then((hit) => hit || fetch(req)).catch(() => caches.match('./index.html')),
    );
    return;
  }
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          caches.open(VERSION).then((c) => c.put(req, copy));
        }
        return res;
      });
    }),
  );
});
